import{_ as a,c as i,o as t,a5 as o}from"./chunks/framework.DqXSAjBk.js";const u=JSON.parse('{"title":"Device API","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"devices/api/index.md","filePath":"devices/api/index.md"}'),s={name:"devices/api/index.md"};function c(r,e,n,d,l,p){return t(),i("div",{"data-pagefind-body":!0},e[0]||(e[0]=[o('<h1 id="device-api" tabindex="-1">Device API <a class="header-anchor" href="#device-api" aria-label="Permalink to &quot;Device API&quot;">​</a></h1><p>The device API is a messaging system for communicating with Lightbug devices. It allows you to send and receive <a href="/docs/pr/21/devices/api/messages/">messages</a> to and from the device, enabling control and data exchange.</p><p>It makes use of the <a href="/docs/pr/21/devices/api/protocol/">Lightbug communication protocol</a>, which is a byte oriented protocol used for device communication.</p><p>This documentation focuses on the higher level element of this API first, including the <a href="/docs/pr/21/devices/api/sdks/toit/">Toit SDK</a>, before working its was down to the <a href="/docs/pr/21/devices/api/messages/">message level</a>, and finally the <a href="/docs/pr/21/devices/api/protocol/">protocol level</a> which underpins it all.</p><p>You can <a href="/docs/pr/21/devices/api/sdks/toit/">get started with Toit quickly</a>, using an SDK built on top of the messages as another layer of abstraction.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><p>The Device API allows you to:</p><ul><li>send commands to the device</li><li>ask for data (GET)</li><li>subscribe to data streams (SUBSCRIBE)</li><li>receive responses, instructions and other data from the device</li></ul><p>On the wire, a single message might look like <code>4c 42 03 0b 00 01 00 00 00 00 00 4b be</code>, however, the API abstracts this away so you can work with high level messaging concepts.</p><h2 id="accessability" tabindex="-1">Accessability <a class="header-anchor" href="#accessability" aria-label="Permalink to &quot;Accessability&quot;">​</a></h2><p>Typically, it can be accessed via UART, I2C, or a UDP network connection.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Device API access depends on the device and may not be supported on all models.</p><p>The <a href="/docs/pr/21/devices/rtk/">RH2 RTK device</a> will be the first general release product to support the API, with a future low cost development board planned.</p><p>For details, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact our support team</a>.</p><p>If you have a supported device, you can <a href="/docs/pr/21/devices/api/sdks/toit/">get started with Toit quickly</a> using the Lightbug SDK, or communicate with the device from other languages using the messages documented here.</p>',16)]))}const m=a(s,[["render",c]]);export{u as __pageData,m as default};
